const cfg = $input.first().json;
if (!cfg.project_id) throw new Error('Set Config.project_id 가 비어 있습니다. 02-input-analyze 결과 project_id 를 넣으세요.');
return [{ json: cfg }];

const cfg = $('Config Ready').first().json;
const start = $('Generate All Sections').first().json;
const backend = String(cfg.backendBase || 'http://127.0.0.1:5050').replace(/\/+$/, '');
const projectId = cfg.project_id;
const pollSeconds = Math.max(5, Number(cfg.generatePollSeconds || 15));
const maxPolls = Math.max(1, Number(cfg.generatePollMax || 120));
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

let last = null;
let polls = 0;
let done = false;
for (let i = 0; i < maxPolls; i++) {
  await sleep(pollSeconds * 1000);
  polls = i + 1;
  last = await this.helpers.httpRequest({
    method: 'GET',
    url: `${backend}/api/projects/${projectId}`,
    json: true,
    timeout: 30000,
  });
  const st = String(last?.status || '');
  if (st === 'completed' || st === 'error') {
    done = true;
    break;
  }
}

if (!done) {
  throw new Error(`generate-all 타임아웃: ${polls}회 폴링 후에도 status=${last?.status || 'unknown'} (progress=${last?.progress ?? '?'})`);
}
if (last?.status === 'error') {
  throw new Error(`generate-all 실패: ${last?.progress_message || 'error'}`);
}

return [{
  json: {
    stage: '04-generate-all-sections',
    project_id: projectId,
    backendBase: backend,
    generateStart: start,
    status: last.status,
    progress: last.progress,
    progress_message: last.progress_message,
    sections_completed: last.sections_completed,
    polls,
    pollSeconds,
    nextStep: '05-export',
    error: null
  }
}];
